insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_inexpensive','inexpensive','adjective','not costing a lot of money','[{"senseId":"inexpensive_1","meaning":"not costing a lot of money","acceptedParaphrases":["cheap","low in price"],"masteryContexts":[{"contextId":"u3_11_inexpensive_meaning","text":"The school canteen serves a healthy and inexpensive lunch every day.","meaning":"not costing much money","wrongMeanings":["costing far too much for most people","made from weak and poor materials","sold for only a short time"]},{"contextId":"u3_11_inexpensive_paraphrase","text":"Rice and beans are an inexpensive way to feed a large family.","meaning":"low in cost","wrongMeanings":["hard to find in the shops","high in quality and price","quick to cook and serve"]}],"situationDistractors":["The restaurant charges fifty pounds for a plain bowl of soup.","The shop sells only luxury chocolates imported from Switzerland.","The meal was free because the chef made a mistake with the order.","Tickets for the food festival sold out within an hour.","The new restaurant uses the finest and rarest produce available.","The waiter forgot to bring the bill to the table."],"gapDistractors":[{"contextId":"u3_11_inexpensive_gap_1","answer":"inexpensive","wrong":["luxurious","expensive","extravagant"]},{"contextId":"u3_11_inexpensive_gap_2","answer":"inexpensive","wrong":["expensive","luxurious","exclusive"]},{"contextId":"u3_11_inexpensive_gap_3","answer":"inexpensive","wrong":["rare","luxurious","forbidden"]}],"spellingErrors":["inexpensiv","inexpensife","inexpencive","inexspensive","unexpensive","inexpensve"],"wordFamilyForms":[{"form":"inexpensive","partOfSpeech":"adjective","example":"The cafe sells inexpensive sandwiches near the station.","pedagogicallyUseful":true},{"form":"expensive","partOfSpeech":"adjective","example":"Fresh seafood is often more expensive than chicken in this region.","pedagogicallyUseful":true,"altExample":"The restaurant was too expensive for the students, so they went to a market instead."},{"form":"expense","partOfSpeech":"noun","example":"Food is the biggest expense for many students living away from home.","pedagogicallyUseful":true,"altExample":"The school covered the expense of the new cooking equipment."}],"masteryPassages":[{"passageId":"u3_11_inexpensive_passage_1","contextId":"u3_11_inexpensive_gap_1","text":"Hana only had five pounds for lunch. Luckily, the market stall sold a hot, ____ meal of rice and vegetables.","answer":"inexpensive"},{"passageId":"u3_11_inexpensive_passage_2","contextId":"u3_11_inexpensive_gap_2","text":"Many students live far from home and have little spending money. They look for ____ restaurants where a full meal costs only a few pounds.","answer":"inexpensive"}],"contextDependentParaphrases":[],"wrongParaphrases":["luxurious","rare","heavy"],"misleadingDistractors":["costing too much for most people","made from poor materials","sold only for a short time"]}]'::jsonb,'["expensive","expense"]'::jsonb,'["relatively inexpensive","fairly inexpensive","inexpensive meal"]'::jsonb,'live'),
('vocab_sodium','sodium','noun','a substance found in salt and in many foods','[{"senseId":"sodium_1","meaning":"a substance found in salt and in many foods","acceptedParaphrases":["a mineral in salt","the element in salt"],"masteryContexts":[{"contextId":"u3_12_sodium_meaning","text":"Crisps and instant noodles often contain a lot of sodium.","meaning":"a substance found in salt","wrongMeanings":["a vitamin found in fruit","a fat used for frying","a sweet substance added to drinks"]},{"contextId":"u3_12_sodium_paraphrase","text":"The nutrition label lists sodium, sugar and fat for each portion.","meaning":"a substance listed on food labels","wrongMeanings":["a type of cooking oil","a kind of fresh herb","a colour added to sweets"]}],"situationDistractors":["The label listed the vitamins found in fresh oranges.","The chef fried the fish in a little sunflower oil.","A bag of sugar was poured into the cake mixture.","The nurse measured the height and weight of each child.","The dessert was sweet because it contained a lot of honey.","The waiter brought a jug of water and some bread."],"gapDistractors":[{"contextId":"u3_12_sodium_gap_1","answer":"sodium","wrong":["carbon","sugar","oil"]},{"contextId":"u3_12_sodium_gap_2","answer":"sodium","wrong":["sugar","fibre","protein"]},{"contextId":"u3_12_sodium_gap_3","answer":"sodium","wrong":["sugar","fat","vinegar"]}],"spellingErrors":["sodeum","soduim","sodiem","sodum","sodiumm","soadium"],"masteryPassages":[{"passageId":"u3_12_sodium_passage_1","contextId":"u3_12_sodium_gap_1","text":"Table salt is made of two elements, chlorine and ____. Nutrition labels often show how much of it a food contains.","answer":"sodium"},{"passageId":"u3_12_sodium_passage_2","contextId":"u3_12_sodium_gap_2","text":"Pupils compared the labels on three kinds of soup. The tinned soup listed the highest amount of ____, so it tasted the saltiest.","answer":"sodium"}],"contextDependentParaphrases":[],"wrongParaphrases":["a vitamin in fruit","a fat in meat","a sugar in milk"],"misleadingDistractors":["a vitamin found in fruit and vegetables","a type of fat used for frying","a sweet substance added to drinks"]}]'::jsonb,'[]'::jsonb,'["low sodium","high sodium","sodium content"]'::jsonb,'live'),
('vocab_commercially','commercially','adverb','in order to sell something and make a profit','[{"senseId":"commercially_1","meaning":"in order to sell something and make a profit","acceptedParaphrases":["as a business","for profit"],"masteryContexts":[{"contextId":"u3_13_commercially_meaning","text":"Bread has been made commercially in large factories for over a century.","meaning":"in order to sell it and make a profit","wrongMeanings":["in order to teach and inform people","in order to save and reuse materials","in order to test and improve ideas"]},{"contextId":"u3_13_commercially_paraphrase","text":"The mushrooms are grown commercially, so they appear in supermarkets all year.","meaning":"on a large scale to sell them","wrongMeanings":["in small pots for pleasure","in secret without permission","by hand without any machines"]}],"situationDistractors":["She baked a cake for her grandmother’s birthday and gave it away.","The students grew tomatoes on the school roof just for fun.","He shared his recipe online without asking for any payment.","The neighbours swapped vegetables over the garden fence.","The teacher explained how bread rises in the oven.","A volunteer cooked soup for the whole street on a cold evening."],"gapDistractors":[{"contextId":"u3_13_commercially_gap_1","answer":"commercially","wrong":["politely","secretly","accidentally"]},{"contextId":"u3_13_commercially_gap_2","answer":"commercially","wrong":["quietly","politely","happily"]},{"contextId":"u3_13_commercially_gap_3","answer":"commercially","wrong":["politely","noisily","sadly"]}],"spellingErrors":["comercially","commercialy","commerciely","commercialley","comersially","commercilly"],"masteryPassages":[{"passageId":"u3_13_commercially_passage_1","contextId":"u3_13_commercially_gap_1","text":"A small family bakery began by baking for neighbours. Now it produces bread ____ and delivers to shops in three cities.","answer":"commercially"},{"passageId":"u3_13_commercially_passage_2","contextId":"u3_13_commercially_gap_2","text":"Some wild berries are tasty but difficult to harvest. They are rarely grown ____, because the cost is higher than the price shoppers will pay.","answer":"commercially"}],"contextDependentParaphrases":[],"wrongParaphrases":["as a hobby","as a gift","as a punishment"],"misleadingDistractors":["in order to teach and inform people","in order to save and reuse materials","in order to test and improve ideas"]}]'::jsonb,'[]'::jsonb,'["commercially available","commercially produced","commercially grown"]'::jsonb,'live'),
('vocab_processed','processed','adjective','changed from its natural form in a factory, often to make it last longer','[{"senseId":"processed_1","meaning":"changed from its natural form in a factory, often to make it last longer","acceptedParaphrases":["factory-made","prepared in a factory"],"masteryContexts":[{"contextId":"u3_14_processed_meaning","text":"Supermarkets sell fresh fruit as well as processed foods such as sausages and tinned soup.","meaning":"changed from the natural form in a factory","wrongMeanings":["kept in its natural form on a farm","grown from seeds in a garden","bought fresh from a local market"]},{"contextId":"u3_14_processed_paraphrase","text":"The shop sells only fresh vegetables, with no processed products such as tinned or frozen food.","meaning":"made or changed in a factory","wrongMeanings":["grown or picked by hand on a farm","cooked or served in a restaurant","washed or sorted in a market"]}],"situationDistractors":["The farmer picked the apples by hand and sold them from a stall.","She bought fresh fish straight from the boat at the harbour.","The family grew their own tomatoes in the garden.","The restaurant cooks every dish from scratch each morning.","The cafe serves salad made from vegetables picked that day.","He drank a glass of water."],"gapDistractors":[{"contextId":"u3_14_processed_gap_1","answer":"processed","wrong":["fresh","raw","natural"]},{"contextId":"u3_14_processed_gap_2","answer":"processed","wrong":["raw","organic","home-grown"]},{"contextId":"u3_14_processed_gap_3","answer":"processed","wrong":["fresh","natural","raw"]}],"spellingErrors":["procesed","prosessed","proccessed","processd","processt","procssed"],"wordFamilyForms":[{"form":"processed","partOfSpeech":"adjective","example":"Tinned beans and frozen pizza are common processed foods.","pedagogicallyUseful":true},{"form":"process","partOfSpeech":"verb","example":"The factory can process thousands of litres of milk every day.","pedagogicallyUseful":true,"altExample":"Machines in the plant wash and process the vegetables before they are frozen."},{"form":"processing","partOfSpeech":"noun","example":"Food processing often adds salt, sugar or preservatives to products.","pedagogicallyUseful":true,"altExample":"The tomatoes go through several stages of processing before they reach the shop."}],"masteryPassages":[{"passageId":"u3_14_processed_passage_1","contextId":"u3_14_processed_gap_1","text":"Ali compared a fresh tomato with ketchup. He learned that ketchup is a ____ food, made by machines from tomatoes, sugar and vinegar.","answer":"processed"},{"passageId":"u3_14_processed_passage_2","contextId":"u3_14_processed_gap_2","text":"The supermarket has two sections. One has fresh fruit and vegetables, and the other has ____ products such as sausages, tinned beans and frozen pizza.","answer":"processed"}],"contextDependentParaphrases":[],"wrongParaphrases":["home-grown","farm-fresh","hand-picked"],"misleadingDistractors":["grown without chemicals on a small farm","cooked fresh at home from raw ingredients","sold only in specialist shops"]}]'::jsonb,'["process","processing"]'::jsonb,'["processed food","processed meat","highly processed"]'::jsonb,'live'),
('vocab_depression','depression','noun','a state of feeling very sad and without hope for a long time','[{"senseId":"depression_1","meaning":"a state of feeling very sad and without hope for a long time","acceptedParaphrases":["long-lasting sadness","low mood that lasts"],"masteryContexts":[{"contextId":"u3_15_depression_meaning","text":"Her depression made even simple daily tasks, such as cooking a meal, feel very hard.","meaning":"a long period of feeling very sad and hopeless","wrongMeanings":["a short period of feeling very tired and bored","a sudden feeling of anger and fear","a long period of feeling very proud"]},{"contextId":"u3_15_depression_paraphrase","text":"Many students find it helpful to talk to a counsellor about depression.","meaning":"a long period of feeling very sad","wrongMeanings":["a fear of being left alone in a place","a habit of eating too much food","a feeling of being very excited about change"]}],"situationDistractors":["He felt a little nervous before the cooking test but enjoyed it afterwards.","The students were excited about the school trip to the market.","She was tired after the long walk and went to bed early.","The team was disappointed to lose the match but laughed about it later that evening.","He was annoyed that the bus was late.","The children were thrilled by the magic show."],"gapDistractors":[{"contextId":"u3_15_depression_gap_1","answer":"depression","wrong":["pride","excitement","curiosity"]},{"contextId":"u3_15_depression_gap_2","answer":"depression","wrong":["laughter","excitement","celebration"]},{"contextId":"u3_15_depression_gap_3","answer":"depression","wrong":["happiness","excitement","curiosity"]}],"spellingErrors":["depresion","depretion","depresssion","deppression","depreshion","depresson"],"wordFamilyForms":[{"form":"depression","partOfSpeech":"noun","example":"Many students find it helpful to talk about depression with someone they trust.","pedagogicallyUseful":true},{"form":"depressed","partOfSpeech":"adjective","example":"Several families felt depressed after hearing the bad news about the factory closing.","pedagogicallyUseful":true,"altExample":"She seemed depressed for weeks, so her friends encouraged her to talk to a counsellor."},{"form":"depressing","partOfSpeech":"adjective","example":"The grey weather and the empty cafe made the evening feel depressing.","pedagogicallyUseful":true,"altExample":"The news about rising food prices was depressing for many families."}],"masteryPassages":[{"passageId":"u3_15_depression_passage_1","contextId":"u3_15_depression_gap_1","text":"Months of bad news left Karim feeling empty and hopeless. His teacher noticed the signs of ____ and suggested a talk with the school counsellor.","answer":"depression"},{"passageId":"u3_15_depression_passage_2","contextId":"u3_15_depression_gap_2","text":"Everyone feels sad sometimes, but ____ is different because the sadness and hopelessness last for weeks or months. Charities help by giving people a place to talk.","answer":"depression"}],"contextDependentParaphrases":[],"wrongParaphrases":["sudden anger","brief excitement","mild boredom"],"misleadingDistractors":["a feeling of being very angry for a short time","a worry about speaking in front of others","a tiredness after a long walk"]}]'::jsonb,'["depressed","depressing"]'::jsonb,'["mild depression","severe depression","teenage depression"]'::jsonb,'live'),
('vocab_overweight','overweight','adjective','heavier than is considered healthy for a person’s height','[{"senseId":"overweight_1","meaning":"heavier than is considered healthy for a person’s height","acceptedParaphrases":["above a healthy weight","carrying extra weight"],"masteryContexts":[{"contextId":"u3_16_overweight_meaning","text":"The survey asked how many children in the region are overweight.","meaning":"heavier than is healthy for their height","wrongMeanings":["taller than is usual for their age","stronger than is needed for sport","older than is allowed for the class"]},{"contextId":"u3_16_overweight_paraphrase","text":"Teachers do not comment on whether a student is overweight, because it can hurt their feelings.","meaning":"heavier than a person’s body needs","wrongMeanings":["carrying more bags than is needed","thinner than is healthy for their height","paid more than is fair for their work"]}],"situationDistractors":["The runner was thin and light and finished the race first.","The boy was shorter than his classmates but ate the same meals.","The nurse measured the height of each child.","She was very strong and could lift heavy boxes easily.","The athlete trained every morning before school started.","The man was very tall and had to bend through the door."],"gapDistractors":[{"contextId":"u3_16_overweight_gap_1","answer":"overweight","wrong":["late","absent","dishonest"]},{"contextId":"u3_16_overweight_gap_2","answer":"overweight","wrong":["dishonest","nervous","ambitious"]},{"contextId":"u3_16_overweight_gap_3","answer":"overweight","wrong":["tall","late","quiet"]}],"spellingErrors":["overwieght","overwait","overweit","overwheight","overweigth","overwaight"],"wordFamilyForms":[{"form":"overweight","partOfSpeech":"adjective","example":"The chart shows which children are overweight for their height.","pedagogicallyUseful":true},{"form":"weight","partOfSpeech":"noun","example":"The nurse recorded each child’s weight and height in a notebook.","pedagogicallyUseful":true,"altExample":"The weight of the flour is printed clearly on the side of the bag."},{"form":"underweight","partOfSpeech":"adjective","example":"The charity gave extra meals to children who were underweight.","pedagogicallyUseful":true,"altExample":"Nurses check whether a baby is underweight at every visit."}],"masteryPassages":[{"passageId":"u3_16_overweight_passage_1","contextId":"u3_16_overweight_gap_1","text":"The nurse weighed and measured every pupil in Year 9. She then compared the results with a chart to see who was ____ for their height.","answer":"overweight"},{"passageId":"u3_16_overweight_passage_2","contextId":"u3_16_overweight_gap_2","text":"The jockey is very small and light. If he were even a little ____, his horse would have to carry extra load and might lose the race.","answer":"overweight"}],"contextDependentParaphrases":[],"wrongParaphrases":["below a healthy height","under a normal age","beyond a safe speed"],"misleadingDistractors":["carrying too much luggage on a journey","weighing less than most people of the same age","very strong and good at sport"]}]'::jsonb,'["weight","underweight"]'::jsonb,'["slightly overweight","overweight children","become overweight"]'::jsonb,'live'),
('vocab_unwell','unwell','adjective','feeling ill, or not in good health','[{"senseId":"unwell_1","meaning":"feeling ill, or not in good health","acceptedParaphrases":["ill","not feeling well"],"masteryContexts":[{"contextId":"u3_17_unwell_meaning","text":"Several guests felt unwell after eating at the street stall, so the owner closed it for the day.","meaning":"ill or not in good health","wrongMeanings":["upset about a bad result","worried about a test","annoyed by the noise"]},{"contextId":"u3_17_unwell_paraphrase","text":"If you are unwell, please stay at home so that you do not pass the illness to others.","meaning":"not healthy","wrongMeanings":["unhappy about the school rules","unable to find a seat","unlikely to arrive on time"]}],"situationDistractors":["He felt full of energy and ran all the way to school.","The students were hungry and queued early for lunch.","She was nervous about the speaking exam.","The twins were bored and played cards on the bus.","The chef was proud of the new menu.","The guests were delighted with the meal."],"gapDistractors":[{"contextId":"u3_17_unwell_gap_1","answer":"unwell","wrong":["proud","generous","curious"]},{"contextId":"u3_17_unwell_gap_2","answer":"unwell","wrong":["proud","generous","curious"]},{"contextId":"u3_17_unwell_gap_3","answer":"unwell","wrong":["cheerful","wealthy","famous"]}],"spellingErrors":["unwel","unwelll","unwhel","onwell","unwll","unweel"],"masteryPassages":[{"passageId":"u3_17_unwell_passage_1","contextId":"u3_17_unwell_gap_1","text":"Sara looked pale and kept holding her stomach during class. The teacher asked if she was ____ and sent her to the nurse.","answer":"unwell"},{"passageId":"u3_17_unwell_passage_2","contextId":"u3_17_unwell_gap_2","text":"The restaurant owner has a strict rule for the kitchen. If any member of staff feels ____, they must stay at home, which protects customers as well as workers.","answer":"unwell"}],"contextDependentParaphrases":[],"wrongParaphrases":["hungry","nervous","bored"],"misleadingDistractors":["feeling very hungry before a meal","feeling happy and full of energy","feeling nervous about an exam"]}]'::jsonb,'[]'::jsonb,'["feel unwell","look unwell","seem unwell"]'::jsonb,'live'),
('vocab_ingredients','ingredients','noun','the different foods that are mixed together to make a dish','[{"senseId":"ingredients_1","meaning":"the different foods that are mixed together to make a dish","acceptedParaphrases":["food items","things in a recipe"],"masteryContexts":[{"contextId":"u3_18_ingredients_meaning","text":"The chef bought all the ingredients for the soup at the local market.","meaning":"the foods used to make a dish","wrongMeanings":["the pans and knives used to cook food","the recipes that cooks write down","the customers who eat the food"]},{"contextId":"u3_18_ingredients_paraphrase","text":"The label lists the ingredients in order, from the largest amount to the smallest.","meaning":"the foods that a product is made from","wrongMeanings":["the prices of all the goods in a shop","the dates when food will go bad","the instructions for heating a meal"]}],"situationDistractors":["The cook washed the pans and put the knives in the drawer.","The waiter wrote the order on a small notepad.","The customers waited outside until the cafe opened.","She followed the instructions to heat the meal for two minutes.","The manager counted the money at the end of the day.","He carried the tray to the table by the window."],"gapDistractors":[{"contextId":"u3_18_ingredients_gap_1","answer":"ingredients","wrong":["plates","tools","guests"]},{"contextId":"u3_18_ingredients_gap_2","answer":"ingredients","wrong":["plates","tools","guests"]},{"contextId":"u3_18_ingredients_gap_3","answer":"ingredients","wrong":["tools","pans","plates"]}],"spellingErrors":["ingrediants","ingreedients","ingredents","ingridients","ingredientz","ingredeints"],"masteryPassages":[{"passageId":"u3_18_ingredients_passage_1","contextId":"u3_18_ingredients_gap_1","text":"To make the sauce, you need tomatoes, garlic and olive oil. Write a list of all the ____ before you go shopping.","answer":"ingredients"},{"passageId":"u3_18_ingredients_passage_2","contextId":"u3_18_ingredients_gap_2","text":"The label on the biscuit packet was very long. It listed all the ____ in order, from the largest amount to the smallest.","answer":"ingredients"}],"contextDependentParaphrases":[],"wrongParaphrases":["kitchen tools","cooking steps","dinner guests"],"misleadingDistractors":["the tools that are used to cook a dish","the steps that are followed to cook a dish","the people who help to cook a dish"]}]'::jsonb,'[]'::jsonb,'["fresh ingredients","key ingredients","natural ingredients"]'::jsonb,'live'),
('vocab_nutritious','nutritious','adjective','containing the substances that the body needs to stay healthy and grow','[{"senseId":"nutritious_1","meaning":"containing the substances that the body needs to stay healthy and grow","acceptedParaphrases":["healthy","good for the body"],"masteryContexts":[{"contextId":"u3_19_nutritious_meaning","text":"The canteen offers a nutritious meal that includes vegetables, rice and fish.","meaning":"containing what the body needs to stay healthy","wrongMeanings":["containing a lot of sugar and cream","made quickly in a hot pan","sold at a very low price"]},{"contextId":"u3_19_nutritious_paraphrase","text":"Beans are cheap, filling and nutritious, which is why they are eaten all over the world.","meaning":"good for the body because of what they contain","wrongMeanings":["popular because of their sweet taste","easy to carry in a bag","able to be kept for years"]}],"situationDistractors":["The cake was covered in thick cream and sweet icing.","The vending machine sold only fizzy drinks and sweets.","He ate a burger and chips every evening at a fast-food stall.","The chef fried the potatoes in a large pan of hot oil.","The dessert was so sweet that nobody could finish it.","The cafe served enormous portions of white bread and butter."],"gapDistractors":[{"contextId":"u3_19_nutritious_gap_1","answer":"nutritious","wrong":["greasy","sugary","salty"]},{"contextId":"u3_19_nutritious_gap_2","answer":"nutritious","wrong":["greasy","sugary","fried"]},{"contextId":"u3_19_nutritious_gap_3","answer":"nutritious","wrong":["greasy","sugary","salty"]}],"spellingErrors":["nutricious","nutritous","nutrishous","nutritiuos","nutritios","nuttritious"],"wordFamilyForms":[{"form":"nutritious","partOfSpeech":"adjective","example":"The school provides a nutritious lunch for every student.","pedagogicallyUseful":true},{"form":"nutrition","partOfSpeech":"noun","example":"The school offers a short course on nutrition for parents and students.","pedagogicallyUseful":true,"altExample":"Cooking and nutrition are taught together in the school’s food technology class."},{"form":"nutritional","partOfSpeech":"adjective","example":"Each packet carries a table of nutritional information.","pedagogicallyUseful":true,"altExample":"Fruit juice has some nutritional value, but it also contains a lot of sugar."}],"masteryPassages":[{"passageId":"u3_19_nutritious_passage_1","contextId":"u3_19_nutritious_gap_1","text":"Sam usually ate chips and sweets for lunch. His mother wanted him to try something more ____, so she packed rice, eggs and fruit.","answer":"nutritious"},{"passageId":"u3_19_nutritious_passage_2","contextId":"u3_19_nutritious_gap_2","text":"Spinach is not the tastiest vegetable, but it is full of vitamins and minerals. Dietitians call it a very ____ food.","answer":"nutritious"}],"contextDependentParaphrases":[],"wrongParaphrases":["sugary","salty","greasy"],"misleadingDistractors":["containing a lot of sugar and fat","tasting sweet and rich","cooked very quickly in hot oil"]}]'::jsonb,'["nutrition","nutritional"]'::jsonb,'["nutritious food","nutritious meal","nutritious diet"]'::jsonb,'live'),
('vocab_moderation','moderation','noun','the act of not doing or having too much of something','[{"senseId":"moderation_1","meaning":"the act of not doing or having too much of something","acceptedParaphrases":["small amounts","sensible amounts"],"masteryContexts":[{"contextId":"u3_20_moderation_meaning","text":"Our teacher says that fast food is fine in moderation, but not as a daily meal.","meaning":"limited, sensible amounts","wrongMeanings":["very large amounts at one time","a rush without thinking","secret amounts that nobody sees"]},{"contextId":"u3_20_moderation_paraphrase","text":"He believes in moderation, so he never eats too much or goes without his favourite food entirely.","meaning":"the habit of not going to extremes","wrongMeanings":["the habit of eating alone at home","the habit of paying too much attention to prices","the habit of copying friends"]}],"situationDistractors":["She ate five slices of cake and then asked for more.","He refused to taste any dessert at the party.","They drank fizzy drinks all day during the holiday.","The diner filled his plate three times at the buffet.","She gave up every kind of sweet food and never ate any.","He ate a whole pizza on his own."],"gapDistractors":[{"contextId":"u3_20_moderation_gap_1","answer":"moderation","wrong":["advance","public","silence"]},{"contextId":"u3_20_moderation_gap_2","answer":"moderation","wrong":["silence","advance","public"]},{"contextId":"u3_20_moderation_gap_3","answer":"moderation","wrong":["silence","speed","luck"]}],"spellingErrors":["moderashun","moderatoin","modaration","moderaton","moderration","moderacion"],"wordFamilyForms":[{"form":"moderation","partOfSpeech":"noun","example":"Our teacher says that fast food is fine in moderation.","pedagogicallyUseful":true},{"form":"moderate","partOfSpeech":"adjective","example":"Add a moderate amount of salt, not too much and not too little.","pedagogicallyUseful":true,"altExample":"The weather in spring is moderate, neither too hot nor too cold."},{"form":"moderately","partOfSpeech":"adverb","example":"The restaurant is moderately priced, so most families can afford it.","pedagogicallyUseful":true,"altExample":"The soup was moderately spicy, which suited most of the class."}],"masteryPassages":[{"passageId":"u3_20_moderation_passage_1","contextId":"u3_20_moderation_gap_1","text":"Mr Lee never gives up his favourite desserts. He simply eats them in ____, one small piece on Sundays.","answer":"moderation"},{"passageId":"u3_20_moderation_passage_2","contextId":"u3_20_moderation_gap_2","text":"The old saying “too much of anything is bad” teaches the value of ____. Even good things can cause problems if you have huge amounts of them.","answer":"moderation"}],"contextDependentParaphrases":[],"wrongParaphrases":["large amounts","exact amounts","hidden amounts"],"misleadingDistractors":["the act of leading a discussion fairly","a strong wish for as much as possible","the habit of refusing something completely"]}]'::jsonb,'["moderate","moderately"]'::jsonb,'["in moderation","with moderation","practise moderation"]'::jsonb,'live')
